schema:
CREATE TABLE clients (client_id INT PRIMARY KEY, name TEXT);
CREATE TABLE accounts (account_id INT PRIMARY KEY, client_id INT, FOREIGN KEY (client_id) REFERENCES clients(client_id));
CREATE TABLE cards (card_id INT PRIMARY KEY, account_id INT, card_type TEXT, FOREIGN KEY (account_id) REFERENCES accounts(account_id));

CREATE TABLE schools (CDSCode TEXT PRIMARY KEY, School TEXT);
CREATE TABLE frpm (CDSCode TEXT PRIMARY KEY, Free_Meal_Count REAL, FOREIGN KEY (CDSCode) REFERENCES schools(CDSCode));
CREATE TABLE satscores (cds TEXT PRIMARY KEY, AvgScrRead INT, FOREIGN KEY (cds) REFERENCES schools(CDSCode));

CREATE TABLE clients (client_id INT PRIMARY KEY, name TEXT);
CREATE TABLE accounts (account_id INT PRIMARY KEY, client_id INT, FOREIGN KEY (client_id) REFERENCES clients(client_id));
CREATE TABLE transactions (trans_id INT PRIMARY KEY, account_id INT, balance REAL, FOREIGN KEY (account_id) REFERENCES accounts(account_id));

